// ─── File: RateLimiterDemo.java ───
package com.bank.ratelimit;

import java.util.logging.*;

public class RateLimiterDemo {
    private static final Logger log = Logger.getLogger("RateLimit");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        // Login endpoint: allow average 2 req/sec, burst up to 5
        TokenBucketLimiter limiter = new TokenBucketLimiter(2.0, 5.0);
        String client = "SAV2001-login";

        log.info("Normal burst of 5 requests (should all pass):");
        for (int i = 1; i <= 5; i++) {
            boolean ok = limiter.allow(client);
            int n = i;
            log.info(() -> "  request " + n + " -> " + (ok ? "ALLOW" : "429 THROTTLE"));
        }

        log.info("Immediate flood of 3 more (bucket empty, should throttle):");
        for (int i = 6; i <= 8; i++) {
            boolean ok = limiter.allow(client);
            int n = i;
            if (!ok) log.warning(() -> "  request " + n + " -> 429 Too Many Requests");
            else log.info(() -> "  request " + n + " -> ALLOW");
        }

        log.info("Wait 2 seconds to refill ~4 tokens, then try again:");
        Thread.sleep(2000);
        boolean ok = limiter.allow(client);
        log.info(() -> "  refilled request -> " + (ok ? "ALLOW" : "429 THROTTLE"));
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
