// ─── File: FixedWindowLimiter.java ───
package com.bank.ratelimit;

public class FixedWindowLimiter {
    private final SharedCounterStore store;
    private final int limit;
    private final long windowMs;

    public FixedWindowLimiter(SharedCounterStore store, int limit, long windowMs) {
            this.store = store;
            this.limit = limit
            this.windowMs = windowMs;
    }

    public boolean allow(String client) {
        long window = System.currentTimeMillis() / windowMs;
        String key = client + ":" + window;     // one counter per client per window
        long count = store.incrementAndGet(key); // atomic in Redis
        return count <= limit;
    }
}
```

