// ─── File: SharedCounterStore.java ───
package com.bank.ratelimit;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

// Stands in for Redis: atomic increments shared across all API servers.
public class SharedCounterStore {
    private final ConcurrentHashMap<String, AtomicLong> counters = new ConcurrentHashMap<>();
    public long incrementAndGet(String key) {
        return counters.computeIfAbsent(key, k -> new AtomicLong()).incrementAndGet();
    }
}
```
